def RealSeminormSubspaceSimilarities (p : Seminorm ℝ X) (n : ℕ) : Prop :=
  ∀ E F : Submodule ℝ X, Module.finrank ℝ E = n → Module.finrank ℝ F = n →
    ∃ T : E ≃ₗ[ℝ] F, ∃ c : ℝ, 0 < c ∧ ∀ x : E, p (T x : X) = c * p (x : X)

